#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <stdint.h>

#define QUEUE_SIZE 16
#define QUEUE_MASK (QUEUE_SIZE - 1)

struct spsc_queue {
	uint8_t buf[QUEUE_SIZE];
	atomic_t write_idx;
	atomic_t read_idx;
};

static struct spsc_queue q;

static int spsc_push(struct spsc_queue *q, uint8_t val)
{
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);

	if ((uint32_t)(w - r) >= QUEUE_SIZE) {
		return -1;
	}

	q->buf[w & QUEUE_MASK] = val;

	atomic_set(&q->write_idx, (atomic_val_t)(w + 1));
	return 0;
}

static int spsc_pop(struct spsc_queue *q, uint8_t *val)
{
	uint32_t r = (uint32_t)atomic_get(&q->read_idx);
	uint32_t w = (uint32_t)atomic_get(&q->write_idx);

	if (r == w) {
		return -1;
	}

	*val = q->buf[r & QUEUE_MASK];

	atomic_set(&q->read_idx, (atomic_val_t)(r + 1));
	return 0;
}

int main(void)
{
	uint8_t val;

	atomic_set(&q.write_idx, 0);
	atomic_set(&q.read_idx, 0);

	spsc_push(&q, 0xAB);
	spsc_push(&q, 0xCD);

	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) == 0) {
		printk("Popped: 0x%02X\n", val);
	}
	if (spsc_pop(&q, &val) != 0) {
		printk("Queue empty as expected\n");
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/dma.h>
#include <string.h>

#define DMA_CHANNEL 0
#define TRANSFER_SIZE 64

static uint8_t src_buf[TRANSFER_SIZE];
static uint8_t dst_buf[TRANSFER_SIZE];
static K_SEM_DEFINE(dma_sem, 0, 1);

static void dma_callback(const struct device *dev, void *user_data,
			 uint32_t channel, int status)
{
	k_sem_give(&dma_sem);
}

int main(void)
{
	const struct device *const dma_dev = DEVICE_DT_GET(DT_NODELABEL(dma0));
	int ret;

	if (!device_is_ready(dma_dev)) {
		printk("DMA device not ready\n");
		return -ENODEV;
	}

	for (int i = 0; i < TRANSFER_SIZE; i++) {
		src_buf[i] = (uint8_t)i;
	}
	memset(dst_buf, 0, sizeof(dst_buf));

	struct dma_block_config block_cfg = {
		.source_address = (uint32_t)src_buf,
		.dest_address = (uint32_t)dst_buf,
		.block_size = TRANSFER_SIZE,
	};

	struct dma_config dma_cfg = {
		.channel_direction = MEMORY_TO_MEMORY,
		.source_data_size = 1,
		.dest_data_size = 1,
		.source_burst_length = 1,
		.dest_burst_length = 1,
		.dma_callback = dma_callback,
		.block_count = 1,
		.head_block = &block_cfg,
	};

	ret = dma_config(dma_dev, DMA_CHANNEL, &dma_cfg);
	if (ret < 0) {
		printk("DMA config failed: %d\n", ret);
		return ret;
	}

	ret = dma_start(dma_dev, DMA_CHANNEL);
	if (ret < 0) {
		printk("DMA start failed: %d\n", ret);
		return ret;
	}

	ret = k_sem_take(&dma_sem, K_SECONDS(1));
	if (ret < 0) {
		printk("DMA transfer timed out\n");
		return ret;
	}

	if (memcmp(src_buf, dst_buf, TRANSFER_SIZE) == 0) {
		printk("DMA transfer successful\n");
	} else {
		printk("DMA transfer verification failed\n");
		return -EIO;
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/drivers/gpio.h>

static const struct gpio_dt_spec led = GPIO_DT_SPEC_GET(DT_ALIAS(led0), gpios);
static const struct gpio_dt_spec button = GPIO_DT_SPEC_GET(DT_ALIAS(sw0), gpios);
static struct gpio_callback button_cb_data;

static void debounce_expiry(struct k_timer *timer)
{
	int val = gpio_pin_get_dt(&button);

	if (val > 0) {
		gpio_pin_toggle_dt(&led);
	}
}

K_TIMER_DEFINE(debounce_tmr, debounce_expiry, NULL);

static void button_isr(const struct device *dev, struct gpio_callback *cb,
		       uint32_t pins)
{
	k_timer_start(&debounce_tmr, K_MSEC(50), K_NO_WAIT);
}

int main(void)
{
	if (!gpio_is_ready_dt(&led) || !gpio_is_ready_dt(&button)) {
		return -1;
	}

	gpio_pin_configure_dt(&led, GPIO_OUTPUT_INACTIVE);
	gpio_pin_configure_dt(&button, GPIO_INPUT | GPIO_PULL_UP);
	gpio_pin_interrupt_configure_dt(&button, GPIO_INT_EDGE_BOTH);
	gpio_init_callback(&button_cb_data, button_isr, BIT(button.pin));
	gpio_add_callback_dt(&button, &button_cb_data);

	k_sleep(K_FOREVER);
	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/bluetooth/bluetooth.h>
#include <zephyr/bluetooth/conn.h>
#include <zephyr/bluetooth/gatt.h>
#include <zephyr/bluetooth/uuid.h>
#include <string.h>

#define TARGET_NAME "Zephyr Peripheral"

static struct bt_conn *default_conn;

static uint8_t discover_cb(struct bt_conn *conn,
			    const struct bt_gatt_attr *attr,
			    struct bt_gatt_discover_params *params)
{
	if (attr == NULL) {
		printk("GATT discovery complete\n");
		return BT_GATT_ITER_STOP;
	}

	printk("GATT service discovered at handle %u\n", attr->handle);
	return BT_GATT_ITER_CONTINUE;
}

static struct bt_gatt_discover_params discover_params = {
	.func = discover_cb,
	.start_handle = BT_ATT_FIRST_ATTRIBUTE_HANDLE,
	.end_handle = BT_ATT_LAST_ATTRIBUTE_HANDLE,
	.type = BT_GATT_DISCOVER_PRIMARY,
};

static void connected(struct bt_conn *conn, uint8_t err)
{
	int ret;

	if (err) {
		printk("Connection failed: %d\n", err);
		bt_conn_unref(default_conn);
		default_conn = NULL;
		return;
	}

	printk("Connected to device\n");

	ret = bt_gatt_discover(conn, &discover_params);
	if (ret) {
		printk("GATT discover failed: %d\n", ret);
	}
}

static void disconnected(struct bt_conn *conn, uint8_t reason)
{
	printk("Disconnected (reason %d)\n", reason);

	if (default_conn == conn) {
		bt_conn_unref(default_conn);
		default_conn = NULL;
	}
}

BT_CONN_CB_DEFINE(conn_callbacks) = {
	.connected = connected,
	.disconnected = disconnected,
};

static bool parse_ad_name(struct bt_data *data, void *user_data)
{
	bool *found = user_data;

	if (data->type == BT_DATA_NAME_COMPLETE ||
	    data->type == BT_DATA_NAME_SHORTENED) {
		if (data->data_len == strlen(TARGET_NAME) &&
		    memcmp(data->data, TARGET_NAME, data->data_len) == 0) {
			*found = true;
			return false;
		}
	}

	return true;
}

static void scan_recv(const struct bt_le_scan_recv_info *info,
		      struct net_buf_simple *buf)
{
	bool found = false;
	int err;

	if (default_conn != NULL) {
		return;
	}

	bt_data_parse(buf, parse_ad_name, &found);

	if (!found) {
		return;
	}

	printk("Target device found, stopping scan and connecting\n");

	bt_le_scan_stop();

	err = bt_conn_le_create(info->addr, BT_CONN_LE_CREATE_CONN,
				BT_LE_CONN_PARAM_DEFAULT, &default_conn);
	if (err) {
		printk("bt_conn_le_create failed: %d\n", err);
		default_conn = NULL;
	}
}

static struct bt_le_scan_cb scan_callbacks = {
	.recv = scan_recv,
};

int main(void)
{
	int err;

	err = bt_enable(NULL);
	if (err) {
		printk("Bluetooth init failed: %d\n", err);
		return err;
	}

	bt_le_scan_cb_register(&scan_callbacks);

	err = bt_le_scan_start(BT_LE_SCAN_ACTIVE, NULL);
	if (err) {
		printk("Scanning failed: %d\n", err);
		return err;
	}

	printk("Scanning for \"%s\"\n", TARGET_NAME);
	k_sleep(K_FOREVER);

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/dfu/mcuboot.h>

static int self_test(void)
{
	/* Basic self-test: verify critical system state */
	printk("Running self-test...\n");
	/* In real application: check peripherals, config, connectivity */
	return 0; /* 0 = pass */
}

int main(void)
{
	int ret;

	if (!boot_is_img_confirmed()) {
		printk("Unconfirmed image — running self-test\n");

		ret = self_test();
		if (ret != 0) {
			return ret;
		}

		ret = boot_write_img_confirmed();
		if (ret < 0) {
			printk("Image confirm failed: %d\n", ret);
			return ret;
		}
		printk("Image confirmed successfully\n");
	} else {
		printk("Image already confirmed\n");
	}

	printk("Application running normally\n");
	k_sleep(K_FOREVER);
	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/fs/nvs.h>
#include <zephyr/storage/flash_map.h>

#define NVS_PARTITION storage_partition
#define NVS_PARTITION_DEVICE FIXED_PARTITION_DEVICE(NVS_PARTITION)
#define NVS_PARTITION_OFFSET FIXED_PARTITION_OFFSET(NVS_PARTITION)
#define NVS_ID 1

static struct nvs_fs fs = {
	.flash_device = NVS_PARTITION_DEVICE,
	.offset = NVS_PARTITION_OFFSET,
	.sector_size = 4096,
	.sector_count = 2,
};

int main(void)
{
	int ret;
	uint32_t write_val = 0xDEADBEEF;
	uint32_t read_val = 0;

	ret = nvs_mount(&fs);
	if (ret < 0) {
		printk("NVS mount failed: %d\n", ret);
		return ret;
	}

	ret = nvs_write(&fs, NVS_ID, &write_val, sizeof(write_val));
	if (ret < 0) {
		printk("NVS write failed: %d\n", ret);
		return ret;
	}

	ret = nvs_read(&fs, NVS_ID, &read_val, sizeof(read_val));
	if (ret < 0) {
		printk("NVS read failed: %d\n", ret);
		return ret;
	}

	if (read_val == write_val) {
		printk("NVS verify OK: 0x%08x\n", read_val);
	} else {
		printk("NVS verify FAIL: wrote 0x%08x, read 0x%08x\n",
		       write_val, read_val);
		return -EIO;
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/watchdog.h>

static volatile int worker_alive;

K_THREAD_STACK_DEFINE(worker_stack, 512);
static struct k_thread worker_thread;

void worker_fn(void *p1, void *p2, void *p3)
{
	while (1) {
		worker_alive = 1;
		printk("Worker alive\n");
		k_sleep(K_MSEC(500));
	}
}

int main(void)
{
	const struct device *const wdt = DEVICE_DT_GET(DT_ALIAS(watchdog0));
	int wdt_channel_id;

	if (!device_is_ready(wdt)) {
		printk("Watchdog device not ready\n");
		return -1;
	}

	struct wdt_timeout_cfg wdt_config = {
		.flags = WDT_FLAG_RESET_SOC,
		.window.min = 0,
		.window.max = 3000,
		.callback = NULL,
	};

	wdt_channel_id = wdt_install_timeout(wdt, &wdt_config);
	if (wdt_channel_id < 0) {
		printk("Watchdog install failed: %d\n", wdt_channel_id);
		return -1;
	}

	int err = wdt_setup(wdt, WDT_OPT_PAUSE_HALTED_BY_DBG);
	if (err < 0) {
		printk("Watchdog setup failed: %d\n", err);
		return -1;
	}

	k_thread_create(&worker_thread, worker_stack,
			K_THREAD_STACK_SIZEOF(worker_stack),
			worker_fn, NULL, NULL, NULL,
			5, 0, K_NO_WAIT);

	while (1) {
		k_sleep(K_SECONDS(1));

		if (worker_alive) {
			worker_alive = 0;
			printk("Feeding WDT\n");
			wdt_feed(wdt, wdt_channel_id);
		} else {
			printk("Worker stalled! Not feeding WDT\n");
		}
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <zephyr/net/mqtt.h>
#include <zephyr/net/socket.h>
#include <string.h>

static struct mqtt_client client;
static struct sockaddr_in broker;
static uint8_t rx_buffer[256];
static uint8_t tx_buffer[256];
static bool connected;

static void mqtt_evt_handler(struct mqtt_client *const c,
			      const struct mqtt_evt *evt)
{
	switch (evt->type) {
	case MQTT_EVT_CONNACK:
		if (evt->result == 0) {
			printk("MQTT connected\n");
			connected = true;
		}
		break;
	case MQTT_EVT_PUBACK:
		printk("MQTT published\n");
		break;
	case MQTT_EVT_DISCONNECT:
		printk("MQTT disconnected\n");
		connected = false;
		break;
	default:
		break;
	}
}

static int publish(struct mqtt_client *c, const char *topic,
		   const char *payload)
{
	struct mqtt_publish_param param = {
		.message.topic.qos = MQTT_QOS_1_AT_LEAST_ONCE,
		.message.topic.topic.utf8 = (uint8_t *)topic,
		.message.topic.topic.size = strlen(topic),
		.message.payload.data = (uint8_t *)payload,
		.message.payload.len = strlen(payload),
		.message_id = 1,
		.dup_flag = 0,
		.retain_flag = 0,
	};

	return mqtt_publish(c, &param);
}

int main(void)
{
	int ret;
	struct zsock_pollfd fds[1];

	mqtt_client_init(&client);

	broker.sin_family = AF_INET;
	broker.sin_port = htons(1883);
	net_addr_pton(AF_INET, "192.168.1.100", &broker.sin_addr);

	client.broker = (struct sockaddr *)&broker;
	client.evt_cb = mqtt_evt_handler;
	client.client_id.utf8 = (uint8_t *)"zephyr_client";
	client.client_id.size = strlen("zephyr_client");
	client.rx_buf = rx_buffer;
	client.rx_buf_size = sizeof(rx_buffer);
	client.tx_buf = tx_buffer;
	client.tx_buf_size = sizeof(tx_buffer);

	ret = mqtt_connect(&client);
	if (ret < 0) {
		printk("MQTT connect failed: %d\n", ret);
		return ret;
	}

	fds[0].fd = client.transport.tcp.sock;
	fds[0].events = ZSOCK_POLLIN;

	while (1) {
		ret = zsock_poll(fds, 1, 500);
		if (ret < 0) {
			printk("MQTT poll error: %d\n", ret);
			break;
		}

		if (ret > 0 && (fds[0].revents & ZSOCK_POLLIN)) {
			ret = mqtt_input(&client);
			if (ret < 0) {
				printk("MQTT input error: %d\n", ret);
				break;
			}
		}

		ret = mqtt_live(&client);
		if (ret < 0) {
			printk("MQTT live error: %d\n", ret);
			break;
		}

		if (connected) {
			ret = publish(&client, "test/topic", "hello");
			if (ret < 0) {
				printk("Publish failed: %d\n", ret);
			}
			connected = false;
		}
	}

	mqtt_disconnect(&client);
	return 0;
}

#include <zephyr/kernel.h>

static volatile int counter;

void timer_expiry(struct k_timer *timer)
{
	counter++;
}

K_TIMER_DEFINE(my_timer, timer_expiry, NULL);

int main(void)
{
	k_timer_start(&my_timer, K_MSEC(500), K_MSEC(500));

	while (1) {
		printk("Counter: %d\n", counter);
		k_sleep(K_SECONDS(2));
	}

	return 0;
}

#include <zephyr/kernel.h>
#include <psa/crypto.h>
#include <string.h>

#define AES_KEY_SIZE 32
#define AES_BLOCK_SIZE 16

static const uint8_t aes_key[AES_KEY_SIZE] = {
	0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
	0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
	0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
	0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
};

static const uint8_t plaintext[AES_BLOCK_SIZE] = {
	'H', 'e', 'l', 'l', 'o', ' ', 'Z', 'e',
	'p', 'h', 'y', 'r', '!', 0x00, 0x00, 0x00,
};

int main(void)
{
	psa_status_t status;
	psa_key_id_t key_id = PSA_KEY_ID_NULL;
	psa_key_attributes_t attributes = PSA_KEY_ATTRIBUTES_INIT;
	uint8_t ciphertext[AES_BLOCK_SIZE + AES_BLOCK_SIZE];
	uint8_t decrypted[AES_BLOCK_SIZE];
	size_t output_len;
	int ret = -1;

	status = psa_crypto_init();
	if (status != PSA_SUCCESS) {
		printk("PSA crypto init failed: %d\n", status);
		goto exit;
	}

	psa_set_key_type(&attributes, PSA_KEY_TYPE_AES);
	psa_set_key_bits(&attributes, 256);
	psa_set_key_algorithm(&attributes, PSA_ALG_CBC_NO_PADDING);
	psa_set_key_usage_flags(&attributes,
				PSA_KEY_USAGE_ENCRYPT | PSA_KEY_USAGE_DECRYPT);

	status = psa_import_key(&attributes, aes_key, sizeof(aes_key), &key_id);
	if (status != PSA_SUCCESS) {
		printk("Key import failed: %d\n", status);
		goto exit;
	}

	status = psa_cipher_encrypt(key_id, PSA_ALG_CBC_NO_PADDING,
				    plaintext, sizeof(plaintext),
				    ciphertext, sizeof(ciphertext),
				    &output_len);
	if (status != PSA_SUCCESS) {
		printk("Encryption failed: %d\n", status);
		goto exit;
	}

	status = psa_cipher_decrypt(key_id, PSA_ALG_CBC_NO_PADDING,
				    ciphertext, output_len,
				    decrypted, sizeof(decrypted),
				    &output_len);
	if (status != PSA_SUCCESS) {
		printk("Decryption failed: %d\n", status);
		goto exit;
	}

	if (memcmp(plaintext, decrypted, sizeof(plaintext)) == 0) {
		printk("AES-256-CBC encrypt/decrypt OK\n");
		ret = 0;
	} else {
		printk("AES-256-CBC verify FAILED\n");
	}

exit:
	if (key_id != PSA_KEY_ID_NULL) {
		status = psa_destroy_key(key_id);
		if (status != PSA_SUCCESS) {
			printk("Key destroy failed: %d\n", status);
			ret = -1;
		}
	}

	psa_reset_key_attributes(&attributes);
	return ret;
}

