{
	int ret;

	ret = sysfs_create_group(&pdev->dev.kobj, &mydev_attr_group);
	if (ret)
		return ret;

	dev_info(&pdev->dev, "mydev: sysfs group created\n");
	return 0;
}

static int mydev_remove(struct platform_device *pdev)
{
	sysfs_remove_group(&pdev->dev.kobj, &mydev_attr_group);
